INSERT INTO `migrations` VALUES ('20260930040000');
-- Vanilla values for the creature display, model and family tables where the client differs.

INSERT INTO `dbc_creaturedisplayinfo` (`ID`, `ModelID`, `SoundID`, `ExtendedDisplayInfoID`, `CreatureModelScale`, `CreatureModelAlpha`, `SizeClass`, `BloodID`, `NPCSoundID`) SELECT `ID`, `ModelID`, `SoundID`, `ExtendedDisplayInfoID`, `CreatureModelScale`, `CreatureModelAlpha`, `SizeClass`, `BloodID`, `NPCSoundID` FROM `vdbc_creaturedisplayinfo` WHERE `ID` IN (3255);
UPDATE `dbc_creaturedisplayinfo` SET
  `ModelID` = (SELECT v.`ModelID` FROM `vdbc_creaturedisplayinfo` v WHERE v.`ID` = `dbc_creaturedisplayinfo`.`ID`),
  `ExtendedDisplayInfoID` = (SELECT v.`ExtendedDisplayInfoID` FROM `vdbc_creaturedisplayinfo` v WHERE v.`ID` = `dbc_creaturedisplayinfo`.`ID`),
  `CreatureModelScale` = (SELECT v.`CreatureModelScale` FROM `vdbc_creaturedisplayinfo` v WHERE v.`ID` = `dbc_creaturedisplayinfo`.`ID`)
WHERE `ID` IN (16, 17, 19, 1614, 14733);
UPDATE `dbc_creaturemodeldata` SET
  `Flags` = (SELECT v.`Flags` FROM `vdbc_creaturemodeldata` v WHERE v.`ID` = `dbc_creaturemodeldata`.`ID`),
  `ModelScale` = (SELECT v.`ModelScale` FROM `vdbc_creaturemodeldata` v WHERE v.`ID` = `dbc_creaturemodeldata`.`ID`),
